import Envoy
import Foundation

// MARK: - Network Client

public enum NetworkClient {
    public static func getCatFact() async throws -> String {
        try await withCheckedThrowingContinuation { continuation in
            DispatchQueue.networking.async {
                let stream = EngineBuilder.demoEngine
                    .streamClient()
                    .newStreamPrototype()
                    .setOnResponseData(closure: { body, _, _ in
                        do {
                            let fact = try JSONDecoder().decode(FactResponse.self, from: body)
                            continuation.resume(returning: fact.fact)
                        } catch {
                            continuation.resume(throwing: FactError.parse)
                        }
                    })
                    .setOnError(closure: { error, _ in
                        continuation.resume(throwing: FactError.network(error))
                    })
                    .start(queue: .networking)

                let headers = RequestHeadersBuilder(
                    method: .get, scheme: "https", authority: "catfact.ninja", path: "/fact"
                ).build()
                stream.sendHeaders(headers, endStream: true)
            }
        }
    }
}

// MARK: - Envoy Engine

private extension EngineBuilder {
    static let demoEngine = EngineBuilder()
        .build()
}

// MARK: - Networking Concurrent Queue

private extension DispatchQueue {
    static let networking = DispatchQueue(label: "io.envoyproxy.envoymobile.networking",
                                          qos: .userInitiated, attributes: .concurrent)
}

// MARK: - Models

private struct FactResponse: Codable {
    let fact: String
}

private enum FactError: LocalizedError {
    case parse
    case network(Error)

    var localizedDescription: String {
        switch self {
        case .parse:
            return "Could not parse fact response"
        case .network(let error):
            return """
                Could not fetch fact
                \(error.localizedDescription)
                """
        }
    }
}

# Generic network-level filter fuzzers overview

Network filters need to be fuzzed. Filters come in two flavors, each with their own fuzzer. Read filters should be added into the [Generic ReadFilter Fuzzer](https://github.com/envoyproxy/envoy/blob/main/test/extensions/filters/network/common/fuzz/network_readfilter_fuzz_test.cc). Write Filters should added into the [Generic WriteFilter Fuzzer](https://github.com/envoyproxy/envoy/blob/main/test/extensions/filters/network/common/fuzz/network_writefilter_fuzz_test.cc). Some filters are both read and write filters: They should be added into both fuzzers.

Before adding the new filter into the fuzzers, please make sure the filter is designed to accept untrusted inputs, or ready to be hardened to accept untrusted inputs.


# Add a new ReadFilter into Generic Readfilter Fuzzer
Only one step is needed to add a new filter to the fuzzer:
* In the file [config.bzl](https://github.com/envoyproxy/envoy/blob/main/test/extensions/filters/network/common/fuzz/config.bzl) the name of the filter has to be added to the `READFILTER_FUZZ_FILTERS` list. The fuzz test will figure the available filters from the factories.
```
READFILTER_FUZZ_FILTERS = [
    "envoy.filters.network.client_ssl_auth",
    "envoy.filters.network.ext_authz",
    "envoy.filters.network.envoy_mobile_http_connection_manager",
    # A dedicated http_connection_manager fuzzer can be found in
    # test/common/http/conn_manager_impl_fuzz_test.cc
    "envoy.filters.network.http_connection_manager",
    "envoy.filters.network.local_ratelimit",
    "envoy.filters.network.rbac",
    # TODO(asraa): Remove when fuzzer sets up connections for TcpProxy properly.
    # "envoy.filters.network.tcp_proxy",
    "the_new_filter_created_by_you", // <---Add the filter name here
]
```

# Add a new WriteFilter into Generic Writefilter Fuzzer
For WriteFilter, the name of the filter must be added into the `WRITEFILTER_FUZZ_FILTERS` list of the file [BUILD](https://github.com/envoyproxy/envoy/blob/main/test/extensions/filters/network/common/fuzz/BUILD).

# Add test cases into corpus
Good test cases can provide good examples for fuzzers to find more paths in the code, increase the coverage and help find bugs more efficiently.
Each test case is a file under the folder [network_readfilter_corpus](https://github.com/envoyproxy/envoy/blob/main/test/extensions/filters/network/common/fuzz/network_readfilter_corpus) or [network_writefilter_corpus](https://github.com/envoyproxy/envoy/blob/main/test/extensions/filters/network/common/fuzz/network_writefilter_corpus). It consists of two parts: `config` and `actions`.
`config` is the protobuf to instantiate a filter, and `actions` are sequences of actions to take in order to test the filter.
An example for testing MongoProxy filter:
```
config {
  name: "envoy.filters.network.mongo_proxy"
  typed_config {
    type_url: "type.googleapis.com/envoy.extensions.filters.network.mongo_proxy.v3.MongoProxy"
    value: "\n\001\\\032\t\032\002\020\010\"\003\010\200t \001"
  }
}
actions {
  on_new_connection {
  }
}
actions {
  on_data {
    data: "\120\0\0\0\1\0\0\0\1\0\0\0\324\7\0\0\4\0\0\0\164\145\163\164\56\164\145\163\164\0\24\0\0\0\377\377\377\377\52\0\0\0\2\163\164\162\151\156\147\137\156\145\145\144\137\145\163\143\0\20\0\0\0\173\42\146\157\157\42\72\40\42\142\141\162\12\42\175\0\0"
  }
}
actions {
  advance_time {
    milliseconds: 10000
  }
}
```
* `config.name` is the name of the filter.
* `config.typed_config.type_url` is the type url of the filter config API.
* `config.typed_config.value` is the serialized string of the config protobuf, and in C++ we can call`config.SerializeAsString()` to obtain this. This string may contain special characters. Recommend using octal or hexadecimal sequence for the string.
* `actions.on_data.data` (or `actions.on_write.data`) is the buffer parameter `data`(in string format) for testing ReadFilter's method onData() (or for testing WriteFilter's method onWrite()). This string may contain special characters. Recommend using octal or hexadecimal sequence for the string.
* `actions.on_data.end_stream` (or `actions.on_write.end_stream`) is the bool parameter `end_stream` for testing ReadFilter's method onData() (or for testing WriteFilter's method onWrite()).
* `actions.on_new_connection` is an action to call `onNewConnection` method of a ReadFilter.
* `actions.advance_time.milliseconds` is the duration in milliseconds for the simulatedSystemTime to advance by.
For more details, see the APIs for [ReadFilter Fuzz Testcase](https://github.com/envoyproxy/envoy/blob/main/test/extensions/filters/network/common/fuzz/network_readfilter_fuzz.proto) and  [WriteFilter Fuzz Testcase](https://github.com/envoyproxy/envoy/blob/main/test/extensions/filters/network/common/fuzz/network_writefilter_fuzz.proto).

## Convert a unit test case to a fuzz test case manually
This section explains an approach to generate a corpus from unit tests. It is an optional step for users who want to generate the highest possible coverage.
Unit test cases usually leads the filter into interesting states. Currently there is no automatic way to convert a unit test case into a fuzz test case. However, there is a way to convert it manually.
We can write a utility function like this and use it to print the `buffer` and `protobuf` as a octal sequence to avoid invisible characters:
```
static std::string toOct(const std::string& source, const std::string& info) {
   std::stringstream ss;
   for (unsigned char c : source) {
     int n=c-'\0';
     ss<<'\\'<<std::oct<<n;
   }
   std::cout<<"info = "<<info<<", string:"<<ss.str()<<std::endl;
   return ss.str();
 }
```
In the unit test code, we temporarily add a function(finally we will remove it) like the above one.
Then we can fill in `config.typed_config.value` with the value returned or printed by
```toOct(config.SerializeAsString(), "config serialized string: ")```
where `config` is the config protobuf in a unit test case.

We can also fill in `actions.on_data.data` or `actions.on_write.data` with the value returned or printed by
```toOct(buffer.toString(), "buffer:")```
where `buffer` is the buffer to pass to `onData()` or `onWrite()` in a unit test case.

Please note that the two fuzzers use the "real input" for fuzzers. If you are using a mock decoder and pass an empty buffer to onData(), that test case won't help cover much code in the fuzzers(but the config protobuf is still helpful).

## Known issues in the fuzzers
* Both of the fuzzers use static helper classes to speed up the fuzz tests. Once there is an issue which is unreproducile by a single testcase, please check the mock objects which are modified by the filters and have states inside (some of them have a vector or a map object inside). Please make sure they are correctly reset or cleared in `UberFilterFuzzer::reset()` or `UberWriteFilterFuzzer::reset()`.
* The fuzzers don't support system calls like file IO or network IO. Please avoid triggering the related function calls by disabling the test case in `UberFilterFuzzer::checkInvalidInputForFuzzer`, or add some mock objects depending on your functionality.

### Overview

The subset load balancer (SLB) divides the upstream hosts in a cluster into one or more subsets. At
request time the SLB uses information from the `LoadBalancerContext` to choose one of its
subsets. Choosing a host is then delegated to the subset's load balancer. If no subset matches the
context, the SLB falls back (depending on configuration) to balancing over a default subset,
balancing over any upstream host in the cluster, or returning no host.

Load balancing within a subset is accomplished by constructing one of the existing load balancer
types with `Upstream::HostSet` that presents a filtered copy of the upstream hosts. All load
balancer types except the Original DST load balancer may be used for subset load balancing.

### Fallback

The SLB can be configured with one of three fallback policies. If no subset matching the
`LoadBalancerContext` is found:

1. `NO_FALLBACK` specifies that `chooseHost` returns `nullptr` and load balancing fails.
2. `ANY_ENDPOINT` specifies that load balancing occurs over the entire set of upstream hosts.
3. `DEFAULT_SUBSET` specifies that load balancing occurs over a specific subset of upstream
   hosts. If the default subset is empty, `chooseHost` returns `nullptr` and load balancing fails.

During construction, if the fallback policy is `ANY_ENDPOINT`, a default subset is constructed
using the original `Upstream::HostSet`. If the fallback policy is `DEFAULT_SUBSET`, but the
configuration does not specify any metadata (e.g. all hosts match), the SLB changes the fallback
policy to `ANY_ENDPOINT`.

### Selecting Subsets

The initial implementation supports selecting subsets by endpoint metadata provided via EDS.

The configuration specifies a list of subset selectors. Each selector is used, in turn, to create
subsets of hosts. The selectors exist to limit the combinations of endpoint metadata used for
creating subsets. We precompute the subsets outside the load balancing path to avoid locking.

Currently the only mechanism for specifying a selector is to provide a list of metadata keys:

``` json
{
  "subset_selectors": [
    { "keys": [ "a", "b" ] },
    { "keys": [ "x" ] }
  ]
}
```

For each selector, the SLB iterates over the hosts and inspects the host's metadata for the
`"envoy.lb"` filter. If a host's metadata provides values for each key, a subset is created for the
metadata. For example, given the selectors above, if a host's metadata contains `{a=1, b=2}`, a
subset is created for `{a=1, b=2}`. Other hosts with `{a=1, b=2}` are also included in the subset.
A host with metadata like `{a=1, b=2, x=3}` is included in two subsets (`{a=1, b=2}` and
{`x=3`}). The same keys may appear in multiple selector entries: it is feasible to have both an
`{a=1, b=2}` subset and an `{a=1}` subset.

On update, the SLB divides the hosts added into the appropriate subset(s) and triggers update
events on the filtered host sets. The SLB also manages the optional "local HostSet" used for
zone-aware routing.

The CDS configuration for the subset selectors is meant to allow future extension. For example:

1. Selecting endpoint metadata keys by a prefix or other string matching algorithm, or
2. Using a list-typed metadata value to allow a single endpoint to have multiple values for a
   metadata key.

Subsets are stored in a trie-like fashion. Keys in the selectors are lexically sorted. An
`LbSubsetMap` is an `unordered_map` of string keys to `ValueSubsetMap`. `ValueSubsetMap` is an
`unordered_map` of (wrapped, see below) `Protobuf::Value` to `LbSubsetEntry`. The
`LbSubsetEntry` may contain an `LbSubsetMap` of additional keys or a `Subset`. `Subset`
encapsulates the filtered `Upstream::HostSet` and `Upstream::LoadBalancer` for a subset.

`Protobuf::Value` is wrapped to provide a cached hash value for the value. Currently,
`Protobuf::Value` is hashed by first encoding the value as a string and then hashing the
string. By wrapping it, we can compute the hash value outside the request path for both the
metadata values provided in `LoadBalancerContext` and those used internally by the SLB.

### Subset Lookup

Currently we require the metadata provided in `LoadBalancerContext` to match a subset exactly in
order to select the subset for load balancing. Changing this behavior has implications for the
performance of the subset selection algorithm. The current algorithm, described below, runs in
`O(N)` time with respect to the number of metadata key-value pairs in the `LoadBalancerContext`.

The metadata key-value pairs from `LoadBalancerContext` must be sorted by key for the algorithm to
work. Currently we expect lexical order, but the sort order doesn't matter as long as both the
context and load balancer use the same ordering. Sorting of the `LoadBalancerContext` keys is
currently handled by `Router::RouteEntryImplBase`.

Given a sequence of N metadata keys and values (previously sorted lexically by key) from
`LoadBalancerContext`, we can look up the appropriate subset in `O(N)` time as follows. It may be
helpful to look at the [diagram](#diagram) provided in the example.

1. Initialize `subsets` to refer to the root `LbSubsetMap` and `entry` to point at a null
   `LbSubsetEntryPtr`.
2. For each key-value in the metadata:
   1. Lookup the key in `subsets` to find a `ValueSubsetMap`. (Average constant time.) If not
      found, exit the loop.
   2. Lookup the value in the `ValueSubsetMap` to find an `LbSubsetEntry`. (Average constant time.)
      If not found, exit the loop.
   3. Assign the `LbSubsetEntry`'s `LbSubsetMap` to `subsets`. (It may be empty.)
   4. If this is the last key-value pair, assign the `LbSubsetEntry` to `entry`.
3. If `entry` has been set and has a `Subset` value, we found a matching subset, delegate balancing
   to the subset's load balancer.
4. Otherwise, execute the fallback policy.

N.B. `O(N)` complexity presumes that the delegate load balancer executes in constant time.

### Example

Assume a set of hosts from EDS with the following metadata, assigned to a single cluster.

Endpoint | stage | version | type   | xlarge
---------|-------|---------|--------|-------
e1       | prod  | 1.0     | std    | true
e2       | prod  | 1.0     | std    |
e3       | prod  | 1.1     | std    |
e4       | prod  | 1.1     | std    |
e5       | prod  | 1.0     | bigmem |
e6       | prod  | 1.1     | bigmem |
e7       | dev   | 1.2-pre | std    |

Note: Only e1 has the "xlarge" metadata key.

Given this CDS `envoy::config::cluster::v3::Cluster`:

``` json
{
  "name": "c1",
  "lb_policy": "ROUND_ROBIN",
  "lb_subset_config": {
    "fallback_policy": "DEFAULT_SUBSET",
    "default_subset": {
      "stage": "prod",
      "version": "1.0",
      "type": "std"
    },
    "subset_selectors": [
      { "keys": [ "stage", "type" ] },
      { "keys": [ "stage", "version" ] },
      { "keys": [ "version" ] },
      { "keys": [ "xlarge", "version" ] },
    ]
  }
}
```

The following subsets are created:

`stage=prod, type=std` (e1, e2, e3, e4)
`stage=prod, type=bigmem` (e5, e6)
`stage=dev, type=std` (e7)
`stage=prod, version=1.0` (e1, e2, e5)
`stage=prod, version=1.1` (e3, e4, e6)
`stage=dev, version=1.2-pre` (e7)
`version=1.0` (e1, e2, e5)
`version=1.1` (e3, e4, e6)
`version=1.2-pre` (e7)
`version=1.0, xlarge=true` (e1)

In addition, a default subset is created:

`stage=prod, type=std, version=1.0` (e1, e2)

