      x = x*2;
      printf("y=%d x=%d\n", y, x);
    }
    /*special_code_end*/
    /*special_code_start:ON_RESTORE_YIELD_STATE*/
    if(0){
      printf("y=%d x=%d\n", y, x);
      x = x/2;
      printf("y=%d x=%d\n", y, x);
    }
    /*special_code_end*/
    printf("ERROR BEFORE YIELD\n");
    exit(1);
  }
  YCF_YIELD();
  if(y != 42 || x != 9){
    printf("ERROR AFTER YIELD\n");
    exit(1);
